  first [ exact SOK
        | eapply store_ok_sub; [ | exact SOK | | ]; rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn [Z.of_nat Pos.of_succ_nat Pos.succ]; lia ].

Definition PMA1G_STACK : Z := 48 + 80.          (* [comment removed for export] *)
Definition PMA1N_STACK : Z := 16 + LSF.         (* [comment removed for export] *)

(* [comment removed for export] *)
Definition FR9 (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes m
     (Z_to_bv 64 (s - 8)) (word_to_le_bytes 8 ret))
     (Z_to_bv 64 (s - 16)) (word_to_le_bytes 8 (getr regs 8)))
     (Z_to_bv 64 (s - 24)) (word_to_le_bytes 8 (getr regs 9)))
     (Z_to_bv 64 (s - 32)) (word_to_le_bytes 8 (getr regs 18)))
     (Z_to_bv 64 (s - 40)) (word_to_le_bytes 8 (getr regs 19)))
     (Z_to_bv 64 (s - 48)) (word_to_le_bytes 8 (getr regs 20)))
     (Z_to_bv 64 (s - 56)) (word_to_le_bytes 8 (getr regs 21)))
     (Z_to_bv 64 (s - 64)) (word_to_le_bytes 8 (getr regs 22)))
     (Z_to_bv 64 (s - 72)) (word_to_le_bytes 8 (getr regs 23)).

Lemma cells9_FR9 : forall m s ret regs, (80 <= s)%Z -> (s < 2 ^ 64)%Z ->
  rdn SEGS (FR9 m s ret regs) (Z_to_bv 64 (s - 8)) 8 = Some (word_to_le_bytes 8 ret) /\
  rdn SEGS (FR9 m s ret regs) (Z_to_bv 64 (s - 16)) 8 = Some (word_to_le_bytes 8 (getr regs 8)) /\
  rdn SEGS (FR9 m s ret regs) (Z_to_bv 64 (s - 24)) 8 = Some (word_to_le_bytes 8 (getr regs 9)) /\
  rdn SEGS (FR9 m s ret regs) (Z_to_bv 64 (s - 32)) 8 = Some (word_to_le_bytes 8 (getr regs 18)) /\
  rdn SEGS (FR9 m s ret regs) (Z_to_bv 64 (s - 40)) 8 = Some (word_to_le_bytes 8 (getr regs 19)) /\
  rdn SEGS (FR9 m s ret regs) (Z_to_bv 64 (s - 48)) 8 = Some (word_to_le_bytes 8 (getr regs 20)) /\
  rdn SEGS (FR9 m s ret regs) (Z_to_bv 64 (s - 56)) 8 = Some (word_to_le_bytes 8 (getr regs 21)) /\
  rdn SEGS (FR9 m s ret regs) (Z_to_bv 64 (s - 64)) 8 = Some (word_to_le_bytes 8 (getr regs 22)) /\
