Section Pma1G.
Context {fx : FPState} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O23Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).

Section Segs.
  Variable rom : word -> option byte.

  (* [comment removed for export] *)
  Lemma pmg_A : forall regs m (s pd pixs sel pp : Z) (v : pixv) (ret : word),
    (48 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> (1 <= sel < 2 ^ 64)%Z -> (0 <= pp)%Z -> (pp + 8 < 2 ^ 64)%Z ->
    PIXat (MA m s ret regs pp) pixs v -> p_d v = 1%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 48)) 48 = true -> store_ok SEGS m (Z_to_bv 64 pp) 8 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pd -> getr regs 11 = Z_to_bv 64 pixs ->
    getr regs 12 = Z_to_bv 64 sel -> getr regs 13 = Z_to_bv 64 pp ->
    exists regs',
      msteps SEGS (mkst regs (0x8f6d4 : word) m rom) (mkst regs' (0x92648 : word) (MA m s ret regs pp) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 48) /\ getr regs' 1 = Z_to_bv 64 0x8f730
      /\ getr regs' 10 = Z_to_bv 64 sel /\ getr regs' 11 = Z_to_bv 64 (s - 44) /\ getr regs' 12 = Z_to_bv 64 (s - 48)
      /\ getr regs' 13 = Z_to_bv 64 0 /\ getr regs' 14 = Z_to_bv 64 0
      /\ getr regs' 8 = Z_to_bv 64 pd /\ getr regs' 9 = Z_to_bv 64 pixs /\ getr regs' 18 = Z_to_bv 64 sel /\ getr regs' 19 = Z_to_bv 64 pp
      /\ regs_agree (fun r => In r [1; 2; 8; 9; 10; 11; 12; 13; 14; 18; 19]%list) regs regs'.
