  (* [comment removed for export] *)
  Lemma pmn_A : forall regs m (s pd pp : Z) (ret : word),
    (48 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= pp)%Z -> (pp + 8 < 2 ^ 64)%Z -> (s <= pp)%Z ->
    rdn SEGS (MA m s ret regs pp) (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) ->
    rdn SEGS (MA m s ret regs pp) (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
    store_ok SEGS m (Z_to_bv 64 (s - 48)) 48 = true -> store_ok SEGS m (Z_to_bv 64 pp) 8 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pd -> getr regs 11 = Z_to_bv 64 0 ->
    getr regs 13 = Z_to_bv 64 pp ->
    exists regs',
      msteps SEGS (mkst regs (0x8f6d4 : word) m rom) (mkst regs' (0x6311c : word) (MA m s ret regs pp) rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret
      /\ getr regs' 10 = Z_to_bv 64 0x10355 /\ getr regs' 11 = Z_to_bv 64 0x1b50b /\ getr regs' 12 = Z_to_bv 64 pd
      /\ getr regs' 8 = getr regs 8 /\ getr regs' 9 = getr regs 9 /\ getr regs' 18 = getr regs 18 /\ getr regs' 19 = getr regs 19
      /\ regs_agree (fun r => In r [1; 2; 8; 9; 10; 11; 12; 18; 19]%list) regs regs'.
Proof.
