(* [comment removed for export] *)
Theorem pma1_nullpixs_W : forall C A m md regs (s pd pp : Z) (ret : word) (S : TSet),
  Cok C -> W C A m md ->
  getr regs 2 = Z_to_bv 64 s -> (s mod 16 = 0)%Z -> (c_top C - LSTK + PMA1N_STACK <= s)%Z -> (s <= c_top C)%Z ->
  getr regs 1 = ret -> ret_ok ret ->
  getr regs 10 = Z_to_bv 64 pd -> getr regs 11 = Z_to_bv 64 0 -> getr regs 13 = Z_to_bv 64 pp ->
  (s <= pp)%Z -> (pp + 8 <= c_top C)%Z -> (0 <= pd < 2 ^ 64)%Z ->
  (forall m' regs', W C A m' md -> cs_kept regs regs' -> POSTM C A s (null_mem m pp) m' -> getr regs' 10 = Z_to_bv 64 pd ->
     realizes SEGS (mkCfg (mkst regs' ret m' al_rom) md) S) ->
  realizes SEGS (mkCfg (mkst regs (0x8f6d4 : word) m al_rom) md) S.
Proof.
